import {Storage, storage} from '../tools/storage';
import {forkSession} from '../messaging/forkSession';

// Only a state generated by this extension may take over the account-page fork.
export const handleAccountFork = async (message: any) => {
	const state = message?.payload?.state;
	const selector = message?.payload?.selector;
	if (typeof state !== 'string' || !state || typeof selector !== 'string' || !selector) return {handled: false};
	const pending = await storage.getItem(`f${state}`, undefined, Storage.LOCAL);
	if (!pending) return {handled: false};
	const response = await forkSession(message);
	return {handled: true, response};
};
